#define main historical_native_main
#include "../dwconv-cuda/main.cu"
#undef main
#include <fstream>
#include <vector>
#include <memory>
#include <cmath>
#include <string>
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
using A4=PackedTensorAccessor32<float,4,RestrictPtrTraits>;using A1=PackedTensorAccessor32<float,1,RestrictPtrTraits>;
std::vector<float>load(std::string name,size_t n){std::vector<float>x(n);std::ifstream f("/home/imo/HeCBench_julia/src/dwconv-julia/"+name,std::ios::binary);f.read((char*)x.data(),n*4);if(!f){fprintf(stderr,"fixture\n");exit(2);}return x;}
struct C{int id,m,k,n=2,c=3,h=11,w=13,oc,oh,ow,ni,nw,nb,no;float*base[4];size_t sizes[4];std::vector<float>oracle;std::unique_ptr<A4>ia,oa,wa;std::unique_ptr<A1>ba;
C(int i,int mul,int ks):id(i),m(mul),k(ks){oc=c*m;oh=h+3-k;ow=w+3-k;ni=n*c*h*w;nw=oc*k*k;nb=oc;no=n*oc*oh*ow;sizes[0]=ni;sizes[1]=no;sizes[2]=nw;sizes[3]=nb;char name[64];snprintf(name,sizeof(name),"study_case%02d_f32.bin",id);auto input=load(name,ni+nw+nb);snprintf(name,sizeof(name),"oracle_case%02d_f32.bin",id);oracle=load(name,no);for(int j=0;j<4;j++){CHECK(cudaMalloc(&base[j],(sizes[j]+32)*4));std::vector<float>guard(sizes[j]+32,-8192);CHECK(cudaMemcpy(base[j],guard.data(),guard.size()*4,cudaMemcpyHostToDevice));}CHECK(cudaMemcpy(base[0]+16,input.data(),ni*4,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(base[2]+16,input.data()+ni,nw*4,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(base[3]+16,input.data()+ni+nw,nb*4,cudaMemcpyHostToDevice));int is[]={n,c,h,w},ist[]={c*h*w,h*w,w,1},os[]={n,oc,oh,ow},ost[]={oc*oh*ow,oh*ow,ow,1},ws[]={oc,1,k,k},wst[]={k*k,k*k,k,1},bs[]={oc},bst[]={1};ia=std::make_unique<A4>(base[0]+16,is,ist);oa=std::make_unique<A4>(base[1]+16,os,ost);wa=std::make_unique<A4>(base[2]+16,ws,wst);ba=std::make_unique<A1>(base[3]+16,bs,bst);}
~C(){for(auto b:base)cudaFree(b);}
void launch(){int blocks=(no+255)/256;if(k==3)conv_depthwise2d_forward_kernel<3,float,float,int><<<blocks,256>>>(*ia,*oa,*wa,*ba,true,no,oc,m,w,h,ow,oh,k,k,1,1,1,1,1,1);else if(k==1)conv_depthwise2d_forward_kernel<1,float,float,int><<<blocks,256>>>(*ia,*oa,*wa,*ba,true,no,oc,m,w,h,ow,oh,k,k,1,1,1,1,1,1);else conv_depthwise2d_forward_kernel<0,float,float,int><<<blocks,256>>>(*ia,*oa,*wa,*ba,true,no,oc,m,w,h,ow,oh,k,k,1,1,1,1,1,1);}};
int main(){std::vector<std::unique_ptr<C>>cases;int id=0;for(int m=1;m<=4;m++)for(int k:{1,3,5})cases.push_back(std::make_unique<C>(++id,m,k));for(auto&c:cases)c->launch();CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){std::vector<float>prefix,outputs,guards;std::vector<double>times;bool ok=true;double error=0;for(auto&ptr:cases){auto&p=*ptr;std::vector<float>sent(p.no+32,-8192);CHECK(cudaMemcpy(p.base[1],sent.data(),sent.size()*4,cudaMemcpyHostToDevice));p.launch();CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int j=0;j<10;j++)p.launch();CHECK(cudaGetLastError());CHECK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10);for(int j:{0,2,3}){std::vector<float>x(p.sizes[j]);CHECK(cudaMemcpy(x.data(),p.base[j]+16,x.size()*4,cudaMemcpyDeviceToHost));prefix.insert(prefix.end(),x.begin(),x.end());}for(int v:{p.m,p.n,p.c,p.h,p.w,p.k,p.oh,p.ow,1,1,1,1,1,1,1,p.no,10,p.k==1||p.k==3?p.k:0})prefix.push_back(float(v));std::vector<float>actual(p.no);CHECK(cudaMemcpy(actual.data(),p.base[1]+16,actual.size()*4,cudaMemcpyDeviceToHost));for(size_t i=0;i<actual.size();i++){double e=abs(double(actual[i])-p.oracle[i]);error=std::max(error,e);ok&=std::isfinite(actual[i])&&e==0;}outputs.insert(outputs.end(),actual.begin(),actual.end());for(int j=0;j<4;j++){std::vector<float>raw(p.sizes[j]+32);CHECK(cudaMemcpy(raw.data(),p.base[j],raw.size()*4,cudaMemcpyDeviceToHost));for(size_t i=0;i<16;i++){guards.push_back(raw[i]);ok&=raw[i]==-8192;}for(size_t i=raw.size()-16;i<raw.size();i++){guards.push_back(raw[i]);ok&=raw[i]==-8192;}}}all&=ok;auto artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());artifact.insert(artifact.end(),guards.begin(),guards.end());std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)artifact.data(),artifact.size()*4);f.close();double total=0;for(auto v:times)total+=v;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":27756,\"max_abs_error\":%.12g,\"max_rel_error\":%s,\"timing_region\":\"sum_all12_source_depthwise_multiplier_kernel_cases_launch_loop_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"timed_cases\":12,\"component_time_seconds\":[",trial,total,ok?"true":"false",error,ok?"0":"null");for(size_t i=0;i<times.size();i++){if(i)printf(",");printf("%.12g",times[i]);}printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),artifact.size());}return all?0:1;}
